import React, { useState, useEffect, useRef, useCallback } from 'react';
import * as d3 from 'd3';
import { FaMale, FaFemale } from "react-icons/fa";
import styles from './StudentFaculty.module.css';
import Title3 from './Title3';

const StudentFaculty = ({ jsonDataPath, title }) => {
    const [data, setData] = useState(null);
    const [filters, setFilters] = useState({});
    const [filteredData, setFilteredData] = useState(null);
    const [showPercentage, setShowPercentage] = useState(true);
    const chartRef = useRef(null);
    const [filterOptions, setFilterOptions] = useState({});
    const [facultadNombres, setFacultadNombres] = useState({});

    // Reference to display total records
    const totalRegistrosRef = useRef(null);

    // Function to remove "id_" prefix from filter names
    const formatFilterLabel = (filterKey) => {
        return filterKey.startsWith('id_') ? filterKey.substring(3) : filterKey;
    };

    // Fetch data and filter options on component mount
    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await fetch(jsonDataPath);
                const jsonData = await response.json();
                setData(jsonData);
                setFilteredData(jsonData); // Initialize filteredData with all data
            } catch (error) {
                console.error('Error fetching data:', error);
            }
        };

        fetchData();

        const filterFiles = [
            'id_sede_cread', 'id_dpto', 'id_pais', 'id_metodologia',
            'id_formacion', 'id_nivel', 'id_facultad', 'id_programa',
            'id_zona', 'id_estrato', 'id_edad'
        ];

        // Dynamically import filter data
        Promise.all(
            filterFiles.map(file =>
                import(`../data/id/${file}.json`)
                    .then(module => ({ key: file, data: module.default }))
                    .catch(error => {
                        console.error(`Error loading filter data for ${file}:`, error);
                        return { key: file, data: [] }; // Return empty array on error
                    })
            )
        ).then(results => {
            const newFilterOptions = {};
            const newFacultadNombres = {};
            results.forEach(({ key, data }) => {
                newFilterOptions[key] = data;
                if (key === 'id_facultad') {
                    data.forEach(item => {
                        newFacultadNombres[item.id] = item.nombre;
                    });
                }
            });
            setFilterOptions(newFilterOptions);
            setFacultadNombres(newFacultadNombres);

            // Initialize filters with all options selected once data is loaded
            setFilters({
                id_facultad: newFilterOptions['id_facultad']?.map(item => item.id) || [],
                id_programa: newFilterOptions['id_programa']?.map(item => item.id) || [],
                id_edad: newFilterOptions['id_edad']?.map(item => item.id) || [],
            });
        });
    }, [jsonDataPath]);

    // Apply filters automatically when filters or data change
    useEffect(() => {
        if (!data) return;

        let currentFiltered = data;
        Object.entries(filters).forEach(([filterKey, filterValues]) => {
            if (filterValues && filterValues.length > 0) {
                currentFiltered = currentFiltered.filter(item => filterValues.includes(item[filterKey]));
            }
        });
        setFilteredData(currentFiltered);
    }, [data, filters]);

    // Update total records display
    useEffect(() => {
        if (totalRegistrosRef.current && filteredData) {
            totalRegistrosRef.current.textContent = `Total de registros: ${filteredData.length}`;
        }
    }, [filteredData]);

    const clearFilters = () => {
        setFilters({
            id_facultad: filterOptions['id_facultad']?.map(item => item.id) || [],
            id_programa: filterOptions['id_programa']?.map(item => item.id) || [],
            id_edad: filterOptions['id_edad']?.map(item => item.id) || [],
        });
        setFilteredData(data); // Reset to all data
    };

    const togglePercentage = () => {
        setShowPercentage(!showPercentage);
    };

    // Prepare data for the grouped bar chart
    const prepareChartData = useCallback(() => {
        if (!filteredData || !facultadNombres || Object.keys(facultadNombres).length === 0) return null;

        const facultyGenderCounts = filteredData.reduce((acc, item) => {
            const facultyId = item.id_facultad;
            const gender = item.genero;
            if (!acc[facultyId]) {
                acc[facultyId] = { M: 0, F: 0 };
            }
            acc[facultyId][gender]++;
            return acc;
        }, {});

        const chartData = Object.keys(facultyGenderCounts).map(facultyId => {
            const maleCount = facultyGenderCounts[facultyId].M || 0;
            const femaleCount = facultyGenderCounts[facultyId].F || 0;
            const totalCount = maleCount + femaleCount;

            const malePercentage = totalCount > 0 ? ((maleCount / totalCount) * 100).toFixed(2) : 0;
            const femalePercentage = totalCount > 0 ? ((femaleCount / totalCount) * 100).toFixed(2) : 0;

            return {
                faculty: facultadNombres[facultyId] || `Facultad ${facultyId}`,
                Hombres: showPercentage ? parseFloat(malePercentage) : maleCount,
                Mujeres: showPercentage ? parseFloat(femalePercentage) : femaleCount,
                rawHombres: maleCount, // Store raw counts for tooltip
                rawMujeres: femaleCount, // Store raw counts for tooltip
                total: totalCount // Total for this faculty
            };
        }).sort((a, b) => a.faculty.localeCompare(b.faculty)); // Sort alphabetically by faculty name

        return chartData;
    }, [filteredData, facultadNombres, showPercentage]);

    // Render the grouped bar chart using D3.js
    const renderChart = useCallback((chartData) => {
        const svg = d3.select(chartRef.current);
        const margin = { top: 20, right: 30, bottom: 90, left: 70 }; // Increased bottom margin for rotated labels
        const width = 650 - margin.left - margin.right;
        const height = 370 - margin.top - margin.bottom;

        svg.selectAll('*').remove(); // Clear previous chart elements

        const g = svg.append('g')
                     .attr('transform', `translate(${margin.left},${margin.top})`);

        const faculties = chartData.map(d => d.faculty);
        const genders = ['Hombres', 'Mujeres'];

        const x0 = d3.scaleBand()
            .domain(faculties)
            .rangeRound([0, width])
            .paddingInner(0.1);

        const x1 = d3.scaleBand()
            .domain(genders)
            .rangeRound([0, x0.bandwidth()])
            .padding(0.05);

        const y = d3.scaleLinear()
            .domain([0, d3.max(chartData, d => Math.max(d.Hombres, d.Mujeres)) * 1.1]) // Max value for y-axis with some padding
            .nice()
            .rangeRound([height, 0]);

        const colors = {
            Hombres: '#507DAF',
            Mujeres: '#FF6384'
        };

        // Bars
        g.selectAll('.faculty-group')
            .data(chartData)
            .enter().append('g')
            .attr('class', 'faculty-group')
            .attr('transform', d => `translate(${x0(d.faculty)},0)`)
            .selectAll('rect')
            .data(d => genders.map(key => ({ key, value: d[key], faculty: d.faculty, rawHombres: d.rawHombres, rawMujeres: d.rawMujeres })))
            .enter().append('rect')
            .attr('x', d => x1(d.key))
            .attr('y', d => y(d.value))
            .attr('width', x1.bandwidth())
            .attr('height', d => height - y(d.value))
            .attr('fill', d => colors[d.key])
            .on('mouseover', function (event, d) {
                const facultyName = d.faculty;
                const programsInFaculty = filteredData.filter(item => facultadNombres[item.id_facultad] === facultyName);

                const programaAgrupado = programsInFaculty.reduce((acc, programItem) => {
                    const programName = filterOptions['id_programa']?.find(p => p.id === programItem.id_programa)?.nombre || `Programa ${programItem.id_programa}`;
                    if (!acc[programName]) {
                        acc[programName] = { mujeres: 0, hombres: 0 };
                    }
                    if (programItem.genero === 'F') {
                        acc[programName].mujeres++;
                    } else {
                        acc[programName].hombres++;
                    }
                    return acc;
                }, {});

                let tooltipContent = `<strong>${facultyName}</strong><br><table><tr><th>Programa</th><th>Mujeres</th><th>Hombres</th><th>Total</th></tr>`;
                Object.entries(programaAgrupado).forEach(([progName, totals]) => {
                    const total = totals.mujeres + totals.hombres;
                    tooltipContent += `<tr><td>${progName}</td><td>${totals.mujeres}</td><td>${totals.hombres}</td><td>${total}</td></tr>`;
                });
                tooltipContent += `</table>`;

                d3.select('#tooltip')
                    .style('opacity', 1)
                    .html(tooltipContent)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 28) + 'px');
            })
            .on('mouseout', function () {
                d3.select('#tooltip').style('opacity', 0);
            });

        // Add value labels on top of each bar
        g.selectAll('.bar-value-label')
            .data(chartData.flatMap(d => genders.map(key => ({ key, value: d[key], faculty: d.faculty, rawValue: d[`raw${key}`] }))))
            .enter().append('text')
            .attr('class', 'bar-value-label')
            .attr('x', d => x0(d.faculty) + x1(d.key) + x1.bandwidth() / 2)
            .attr('y', d => y(d.value) - 5) // Position slightly above the bar
            .attr('text-anchor', 'middle')
            .style('font-size', '0.6em')
            .text(d => showPercentage ? `${d.value.toFixed(2)}%` : d.rawValue); // Show raw value or percentage

        // Axes
        g.append('g')
            .attr('class', 'x-axis')
            .attr('transform', `translate(0,${height})`)
            .call(d3.axisBottom(x0))
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end')
            .attr('dx', '-.8em')
            .attr('dy', '.15em');

        g.append('g')
            .attr('class', 'y-axis')
            .call(d3.axisLeft(y).ticks(null, showPercentage ? '%' : 's'));

        // Tooltip div (append to body once)
        if (d3.select('body').select('#tooltip').empty()) {
            d3.select('body').append('div')
                .attr('id', 'tooltip')
                .attr('class', 'tooltip')
                .style('opacity', 0)
                .style('background-color', 'white')
                .style('border', 'solid')
                .style('border-width', '1px')
                .style('border-radius', '5px')
                .style('padding', '10px')
                .style('position', 'absolute');
        }
    }, [filteredData, facultadNombres, filterOptions, showPercentage]);

    // Re-render chart when filtered data or display mode changes
    useEffect(() => {
        if (chartRef.current) {
            d3.select(chartRef.current).selectAll('*').remove(); // Clear SVG before drawing
            const chartData = prepareChartData();
            if (chartData && chartData.length > 0) {
                renderChart(chartData);
            }
        }
    }, [filteredData, showPercentage, prepareChartData, renderChart]);

    const handleFilterChange = (filterKey, value) => {
        setFilters(prev => {
            const filterValues = prev[filterKey] || [];
            return filterValues.includes(value)
                ? { ...prev, [filterKey]: filterValues.filter(v => v !== value) }
                : { ...prev, [filterKey]: [...filterValues, value] };
        });
    };

    const filtrosEspecificos = ['id_sede_cread', 'id_dpto', 'id_pais', 'id_metodologia', 'id_formacion', 'id_nivel', 'id_zona', 'id_estrato'];
    const filtrosVisibles = Object.entries(filterOptions)
        .filter(([filterKey]) => filtrosEspecificos.includes(filterKey))
        .reduce((obj, [key, val]) => Object.assign(obj, { [key]: val }), {});

    return (
        <div className={styles.stfaContainer}>
            <Title3>{title}</Title3>
            <div className={styles.stfaFilters}>
                <div className={styles.filtersGrid}>
                    {Object.entries(filtrosVisibles).map(([filterKey, options]) => (
                        <div key={filterKey}>
                            <h3>{formatFilterLabel(filterKey)}</h3>
                            <div className={styles.filterItemsContainer}>
                                {options.map(option => (
                                    <label key={option.id}>
                                        <input
                                            type="checkbox"
                                            value={option.id}
                                            checked={filters[filterKey]?.includes(option.id) || false}
                                            onChange={() => handleFilterChange(filterKey, option.id)}
                                        />
                                        {option.nombre || option.id}
                                    </label>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
                {/* "Filtrar" button removed, filtering is automatic */}
                <button onClick={clearFilters}>Limpiar Filtros</button>
            </div>
            <div className={styles.stfaChartContainer}>
                <div className={styles.stfaLegend}>
                    <div className={styles.stfaLegendItem}>
                        <FaFemale className={styles.stfaIcon} style={{ color: "#FF6384" }} size={40} />
                        Mujeres
                    </div>
                    <div className={styles.stfaLegendItem}>
                        <FaMale className={styles.stfaIcon} style={{ color: "#507DAF" }} size={40} />
                        Hombres
                    </div>
                </div>
                <div className={styles.stfatotalRegistros} ref={totalRegistrosRef}>
                    <div className={styles.stfatotalRegistrosName}>
                        Total de registros:
                    </div>
                    <div className={styles.stfatotalRegistrosValue}>
                        {filteredData ? filteredData.length : 0}
                    </div>
                </div>
                <svg ref={chartRef} width="650" height="420"></svg>
                <button onClick={togglePercentage}>
                    {showPercentage ? 'Mostrar números' : 'Mostrar porcentajes'}
                </button>
            </div>
        </div>
    );
};

export default StudentFaculty;