import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import Title2 from '../../utils/Title2';
import Description from '../../utils/Description';
import GraduadoSex from '../../utils/GraduadoSex';

const GraduatesSection = ({ semester }) => {
  const { hash } = useLocation();

  useEffect(() => {
    if (hash) {
      const id = hash.substring(1); // elimina el '#' del hash
      const element = document.getElementById(id);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
      }
    }
  }, [hash]);

  return (
    <section>
        <div id="informacion-graduado">       
                <Title2>Graduados </Title2>
                <Description>
                        El Observatorio Laboral para la Educación, parte del Ministerio de Educación Nacional, analiza la pertinencia de la educación superior mediante el seguimiento de graduados en Colombia y su inserción laboral. Proporciona datos sobre la oferta de graduados, sus perfiles, ingresos y vinculación al sector formal de la economía.
                        Para las instituciones de educación superior, conocer la opinión de sus estudiantes y graduados es vital. Esta retroalimentación enriquece los procesos formativos, permitiendo identificar áreas de mejora, reestructurar programas académicos y promover la formación continua.
                </Description>
        </div>

         <div id="genero-graduado"> 
                <GraduadoSex jsonDataPath={`${process.env.PUBLIC_URL}/data/${semester}/programs/graduados.json`}
                        title="Graduados por Genero" />
        </div>

        
    </section>
  );
};

export default GraduatesSection;
