import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import * as d3 from 'd3';
import { FaGlobe, FaAward } from 'react-icons/fa';
import styles from './ProgramsAcreditedFaculty.module.css';
import Title3 from './Title3';

const ProgramsAcreditedFaculty = ({ jsonDataPath, title }) => {
  const [data, setData] = useState([]);
  const [filterOptions, setFilterOptions] = useState({});
  const [filters, setFilters] = useState({});
  const [countMethod, setCountMethod] = useState('id_programa');
  const [filteredData, setFilteredData] = useState([]);
  const [facultyNames, setFacultyNames] = useState({});
  const [programNames, setProgramNames] = useState({});
  const [agencyNames, setAgencyNames] = useState({});
  const chartRef = useRef(null);

  // Función genérica para cargar JSONs de mapeo
  const loadJSON = useCallback(async (fileName, setter) => {
    try {
      const module = await import(`../data/id/${fileName}.json`);
      setter(module.default);
    } catch (err) {
      console.error(`Error loading ${fileName}.json:`, err);
    }
  }, []);

  // Cargar datos y configuraciones iniciales
  useEffect(() => {
    fetch(jsonDataPath)
      .then(res => res.json())
      .then(jsonData => {
        setData(jsonData);
        setFilteredData(jsonData);
      })
      .catch(err => console.error('Error fetching main data:', err));

    // Opciones de filtros
    const files = ['id_programa', 'id_acreditacion', 'id_facultad', 'id_formacion', 'id_nivel', 'id_metodologia'];
    files.forEach(file =>
      loadJSON(file, items => setFilterOptions(prev => ({ ...prev, [file]: items })))
    );

    // Mapas de nombres para labels
    loadJSON('id_facultad', items => {
      const map = {};
      items.forEach(i => (map[i.id] = i.nombre));
      setFacultyNames(map);
    });
    loadJSON('id_programa', items => {
      const map = {};
      items.forEach(i => (map[i.id] = i.nombre));
      setProgramNames(map);
    });
    loadJSON('id_agencia', items => {
      const map = {};
      items.forEach(i => (map[i.id] = i.nombre));
      setAgencyNames(map);
    });
  }, [jsonDataPath, loadJSON]);

  // Inicializar filtros
  useEffect(() => {
    if (Object.keys(filterOptions).length > 0) {
      const init = {};
      Object.keys(filterOptions).forEach(key => (init[key] = []));
      setFilters(init);
    }
  }, [filterOptions]);

  // Aplicar filtros manualmente
  const applyFilters = useCallback(() => {
    let result = data;
    Object.entries(filters).forEach(([key, vals]) => {
      if (vals.length) result = result.filter(i => vals.includes(i[key]));
    });
    setFilteredData(result);
  }, [data, filters]);

  const clearFilters = () => {
    const reset = {};
    Object.keys(filterOptions).forEach(k => (reset[k] = []));
    setFilters(reset);
    setFilteredData(data);
  };

  const toggleCountMethod = () => {
    setCountMethod(prev => (prev === 'id_programa' ? 'SNIES' : 'id_programa'));
  };

  // Preparar datos para la gráfica
  const prepareChartData = useCallback(() => {
    if (!filteredData.length) return null;
    const grouped = {};
    filteredData.forEach(item => {
      const fac = facultyNames[item.id_facultad] || 'Sin Facultad';
      if (!grouped[fac]) grouped[fac] = { AltaCalidad: [], Internacional: [] };
      if (item.id_acreditacion === 2) grouped[fac].AltaCalidad.push(item);
      if (item.id_acreditacion === 1) grouped[fac].Internacional.push(item);
    });
    const labels = Object.keys(grouped);
    const countUnique = records => new Set(records.map(r => r[countMethod])).size;
    const altaCounts = labels.map(l => countUnique(grouped[l].AltaCalidad));
    const interCounts = labels.map(l => countUnique(grouped[l].Internacional));
    const totalAlta = altaCounts.reduce((sum, v) => sum + v, 0);
    const totalInter = interCounts.reduce((sum, v) => sum + v, 0);
    const pctAlta = labels.map((_, i) => (totalAlta ? ((altaCounts[i] / totalAlta) * 100).toFixed(1) : 0));
    const pctInter = labels.map((_, i) => (totalInter ? ((interCounts[i] / totalInter) * 100).toFixed(1) : 0));
    return { labels, altaCounts, interCounts, pctAlta, pctInter, details: grouped };
  }, [filteredData, facultyNames, countMethod]);

  const chartData = useMemo(() => prepareChartData(), [prepareChartData]);

  // Renderizar gráfica con D3
  const renderChart = useCallback(() => {
    if (!chartData) return;
    const svg = d3.select(chartRef.current);
    const { labels, altaCounts, interCounts, pctAlta, pctInter, details } = chartData;
    const width = 800;
    const height = 400;
    const margin = { top: 20, right: 30, bottom: 100, left: 60 };
    svg.selectAll('*').remove();

    const x0 = d3.scaleBand()
      .domain(labels)
      .range([margin.left, width - margin.right])
      .padding(0.1);
    const x1 = d3.scaleBand()
      .domain(['Alta Calidad', 'Internacional'])
      .range([0, x0.bandwidth()])
      .padding(0.05);
    const y = d3.scaleLinear()
      .domain([0, d3.max([...altaCounts, ...interCounts])])
      .nice()
      .range([height - margin.bottom, margin.top]);
    const color = d3.scaleOrdinal(['#507DAF', '#F4A261']);
    const g = svg.append('g');

    // Tooltip
    let tooltip = d3.select('#tooltip');
    if (tooltip.empty()) {
      tooltip = d3.select('body')
        .append('div')
        .attr('id', 'tooltip')
        .attr('class', styles.tooltip)
        .style('position', 'absolute')
        .style('pointer-events', 'none')
        .style('opacity', 0);
    }

    // Dibujar barras y manejar eventos
    g.selectAll('.facGroup')
      .data(labels)
      .enter()
      .append('g')
      .attr('class', 'facGroup')
      .attr('transform', d => `translate(${x0(d)},0)`)  
      .each(function (fac, i) {
        const group = d3.select(this);
        const arr = [
          { key: 'Alta Calidad', val: altaCounts[i], pct: pctAlta[i], recs: details[fac].AltaCalidad },
          { key: 'Internacional', val: interCounts[i], pct: pctInter[i], recs: details[fac].Internacional }
        ];
        group.selectAll('rect')
          .data(arr)
          .enter()
          .append('rect')
          .attr('x', d => x1(d.key))
          .attr('y', d => y(d.val))
          .attr('width', x1.bandwidth())
          .attr('height', d => y(0) - y(d.val))
          .attr('fill', d => color(d.key))
          .on('mouseover', (e, d) => {
            // Generar filas de tooltip
            const rows = Array.from(new Set(d.recs.map(r => {
              const p = programNames[r.id_programa] || r.id_programa;
              const a = agencyNames[r.id_agencia] || r.id_agencia;
              return `<tr class="${styles.tooltipRow}"><td class="${styles.tooltipCell}">${p}</td><td class="${styles.tooltipCell}">${a}</td></tr>`;
            }))).join('');
            // Mostrar tabla en tooltip
            tooltip.html(`
              <table class="${styles.tooltipTable}">
                <thead>
                  <tr>
                    <th class="${styles.tooltipCell}">Programa</th>
                    <th class="${styles.tooltipCell}">Agencia</th>
                  </tr>
                </thead>
                <tbody>${rows}</tbody>
              </table>
            `)
              .style('opacity', 1)
              .style('left', `${e.pageX + 10}px`)
              .style('top', `${e.pageY - 28}px`);
          })
          .on('mouseout', () => tooltip.style('opacity', 0));
        group.selectAll('text')
          .data(arr)
          .enter()
          .append('text')
          .attr('x', d => x1(d.key) + x1.bandwidth() / 2)
          .attr('y', d => y(d.val) - 5)
          .attr('text-anchor', 'middle')
          .style('font-size', '10px')
          .text(d => `${d.pct}%`);
      });

    // Ejes X e Y
    g.append('g')
      .attr('transform', `translate(0,${height - margin.bottom})`)
      .call(d3.axisBottom(x0))
      .selectAll('text')
      .attr('transform', 'rotate(-45)')
      .style('text-anchor', 'end');

    g.append('g')
      .attr('transform', `translate(${margin.left},0)`)
      .call(d3.axisLeft(y));
  }, [chartData, programNames, agencyNames]);

  // Renderizar al actualizar datos
  useEffect(() => { renderChart(); }, [renderChart]);

  // Limpiar tooltip al desmontar
  useEffect(() => () => d3.select('#tooltip').remove(), []);

  // Calcular total de acreditaciones
  const totalAcred = chartData
    ? chartData.altaCounts.reduce((sum, v) => sum + v, 0) + chartData.interCounts.reduce((sum, v) => sum + v, 0)
    : 0;

  return (
    <div className={styles.container}>
      <Title3>{title}</Title3>
      <div className={styles.filterAndButtonContainer}>
        <div className={styles.filters}>
          {Object.entries(filterOptions).map(([key, opts]) => (
            <div key={key} className={styles.filter}>
              <h3>{key.replace('id_', '')}</h3>
              <div className={styles.filterItems}>
                {opts.map(o => (
                  <label key={o.id}>
                    <input
                      type="checkbox"
                      value={o.id}
                      checked={filters[key]?.includes(o.id) || false}
                      onChange={() =>
                        setFilters(prev => ({
                          ...prev,
                          [key]: prev[key]?.includes(o.id)
                            ? prev[key].filter(v => v !== o.id)
                            : [...(prev[key] || []), o.id]
                        }))
                      }
                    /> {o.nombre}
                  </label>
                ))}
              </div>
            </div>
          ))}
        </div>
        <div className={styles.buttonContainer}>
          <button onClick={clearFilters}>Limpiar</button>
          <button onClick={applyFilters}>Filtrar</button>
        </div>
      </div>
      <div className={styles.toggleContainer}>
        <button onClick={toggleCountMethod}>
          {countMethod === 'id_programa' ? 'Contar por SNIES' : 'Contar por Programa'}
        </button>
      </div>
      <div className={styles.legend}>
        <div className={styles.legendItem}>
          <FaAward className={`${styles.icon} ${styles.iconAlta}`} /> Alta Calidad
        </div>
        <div className={styles.legendItem}>
          <FaGlobe className={`${styles.icon} ${styles.iconInter}`} /> Internacional
        </div>
      </div>
      <div className={styles.totalAcreditaciones}>
        Total de acreditaciones: <strong>{totalAcred}</strong>
      </div>
      <div className={styles.chartContainer}>
        <svg ref={chartRef} width="800" height="400" />
      </div>
      <div id="tooltip" className={styles.tooltip} />
    </div>
  );
};

export default ProgramsAcreditedFaculty;






