import React, { useState, useEffect, useRef, useCallback } from 'react';
import * as d3 from 'd3';
import { FaMale, FaFemale } from "react-icons/fa";
import styles from './GraduadoSex.module.css';
import Title3 from './Title3';

const GraduadoSex = ({ jsonDataPath, title }) => {
    const [data, setData] = useState(null);
    const [filters, setFilters] = useState({});
    const [filteredData, setFilteredData] = useState(null);
    const chartRef = useRef(null);
    const [filterOptions, setFilterOptions] = useState({});

    // Loads the main data and filter options data
    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await fetch(jsonDataPath);
                const jsonData = await response.json();
                setData(jsonData);
                setFilteredData(jsonData);
            } catch (error) {
                console.error('Error fetching main data:', error);
            }
        };

        fetchData();

        const filterFiles = [
            'sede', 'cread', 'modalidad', 'metodologia',
            'nivel', 'facultad', 'programa'
        ];

        filterFiles.forEach(file => {
            // CORRECTED PATH HERE: 'fk' instead of 'id'
            import(`../data/fk/${file}.json`)
                .then(module => {
                    const fileData = module.default;
                    setFilterOptions(prev => ({ ...prev, [file]: fileData }));
                })
                .catch(error => console.error(`Error loading filter data for ${file}:`, error));
        });
    }, [jsonDataPath]);

    // Initializes filters once filter options are loaded
    useEffect(() => {
        if (Object.keys(filterOptions).length > 0) {
            const newFilters = {};
            Object.keys(filterOptions).forEach(key => {
                newFilters[key] = [];
            });
            setFilters(newFilters);
        }
    }, [filterOptions]);

    // Applies filters to data whenever filters or original data change
    const applyFilters = useCallback(() => {
        if (!data) return;
        let currentFiltered = data;

        Object.entries(filters).forEach(([filterKey, filterValues]) => {
            if (filterValues.length > 0) {
                currentFiltered = currentFiltered.filter(item => {
                    return filterValues.includes(item[filterKey]);
                });
            }
        });
        setFilteredData(currentFiltered);
    }, [data, filters]);

    // This useEffect will call applyFilters whenever 'filters' or 'data' change.
    useEffect(() => {
        applyFilters();
    }, [filters, data, applyFilters]);

    const clearFilters = () => {
        const newFilters = {};
        Object.keys(filterOptions).forEach(key => {
            newFilters[key] = [];
        });
        setFilters(newFilters);
    };

    const prepareChartData = useCallback(() => {
        if (!filteredData) return null;

        const genderData = filteredData.reduce((acc, item) => {
            acc[item.genero] = (acc[item.genero] || 0) + 1;
            return acc;
        }, { M: 0, F: 0 });

        const total = genderData.M + genderData.F;
        const malePercentage = total > 0 ? ((genderData.M / total) * 100).toFixed(2) : 0;
        const femalePercentage = total > 0 ? ((genderData.F / total) * 100).toFixed(2) : 0;

        return {
            labels: ['Hombres', 'Mujeres'],
            series: [malePercentage, femalePercentage],
            counts: [genderData.M, genderData.F],
            total: total
        };
    }, [filteredData]);

    const renderChart = useCallback((chartData) => {
        const svg = d3.select(chartRef.current);
        const width = 300;
        const height = 300;
        const radius = Math.min(width, height) / 2;
        svg.selectAll('*').remove();

        const g = svg.append('g')
            .attr('transform', `translate(${width / 2}, ${height / 2})`);

        const color = d3.scaleOrdinal(['#507DAF', '#FF6384']);
        const pie = d3.pie().value(d => d);

        const dataReady = pie(chartData.series).map((d, i) => {
            d.count = chartData.counts[i];
            d.label = chartData.labels[i];
            return d;
        });
        const arc = d3.arc().innerRadius(radius * 0.5).outerRadius(radius);

        g.selectAll('path')
            .data(dataReady)
            .enter().append('path')
            .attr('d', arc)
            .attr('fill', (d, i) => color(i))
            .attr('stroke', 'white')
            .style('stroke-width', '2px')
            .on('mouseover', function(event, d) {
                let tooltip = d3.select('#tooltip');
                if (tooltip.empty()) {
                    tooltip = d3.select('body').append('div')
                        .attr('id', 'tooltip')
                        .attr('class', 'tooltip')
                        .style('position', 'absolute')
                        .style('pointer-events', 'none');
                }
                tooltip.style('opacity', 1)
                    .html(`<strong>${d.label}</strong>: ${d.count} graduados`)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 28) + 'px');
            })
            .on('mouseout', function() {
                d3.select('#tooltip').style('opacity', 0);
            });

        g.selectAll('text.percentage')
            .data(dataReady)
            .enter().append('text')
            .attr('class', 'percentage')
            .text(d => `${d.data}%`)
            .attr('transform', d => `translate(${arc.centroid(d)})`)
            .style('text-anchor', 'middle')
            .style('font-size', '16px')
            .style('fill', 'white');

        g.append('text')
            .attr('class', 'total-value')
            .attr('text-anchor', 'middle')
            .attr('y', 20)
            .style('font-size', '24px')
            .style('fill', '#333')
            .text(chartData.total);

        g.append('text')
            .attr('class', 'total-label')
            .attr('text-anchor', 'middle')
            .attr('y', 45)
            .style('font-size', '16px')
            .style('fill', '#666')
            .text('Graduados');
    }, []);

    useEffect(() => {
        if (chartRef.current) {
            d3.select(chartRef.current).selectAll('*').remove();
            const chartData = prepareChartData();
            if (chartData) {
                renderChart(chartData);
            }
        }
    }, [filteredData, prepareChartData, renderChart]);

    const handleFilterChange = (filterKey, value) => {
        setFilters(prev => {
            const filterValues = prev[filterKey] || [];
            return filterValues.includes(value)
                ? { ...prev, [filterKey]: filterValues.filter(v => v !== value) }
                : { ...prev, [filterKey]: [...filterValues, value] };
        });
    };

    const filtrosVisibles = Object.entries(filterOptions)
        .filter(([filterKey]) => filterKey !== 'genero' && filterKey !== 'programas' && filterKey !== 'snies')
        .reduce((obj, [key, val]) => ({ ...obj, [key]: val }), {});

    const formatFilterLabel = (filterKey) => {
        return filterKey.charAt(0).toUpperCase() + filterKey.slice(1);
    };

    return (
        <div className={styles.container}>
            <Title3>{title}</Title3>
            <div className={styles.filtersGrid}>
                {Object.entries(filtrosVisibles).map(([filterKey, options]) => (
                    <div key={filterKey} className={styles.filter}>
                        <h3>{formatFilterLabel(filterKey)}</h3>
                        <div className={styles.filterItemsContainer}>
                            {options.map(option => (
                                <label key={option.id}>
                                    <input
                                        type="checkbox"
                                        value={option.id}
                                        checked={filters[filterKey]?.includes(option.id) || false}
                                        onChange={() => handleFilterChange(filterKey, option.id)}
                                    />
                                    {option.name || option.nombre || option.id}
                                </label>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
            <div className={styles.buttonContainer}>
                <button onClick={clearFilters}>Limpiar Filtros</button>
            </div>
            <div className={styles.chartContainer}>
                <div className={styles.legend}>
                    <div className={styles.legendItem}>
                        <FaFemale className={styles.icon} style={{ color: "#FF6384" }} size={40} />
                        Mujeres
                    </div>
                    <div className={styles.legendItem}>
                        <FaMale className={styles.icon} style={{ color: "#507DAF" }} size={40} />
                        Hombres
                    </div>
                </div>
                <svg ref={chartRef} width="300" height="300"></svg>
            </div>
        </div>
    );
};

export default GraduadoSex;
