import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import '../styles/NavBar.css';

const menuItems = [
  {
    name: 'ACADEMICO',
    subMenus: [
      {
        name: 'Acreditación',
        items: [
          { label: 'Información', path: '/academic/accreditation#info-acreditaciones' },
          { label: 'Distribución', path: '/academic/accreditation#distribucion-acreditaciones' },
          { label: 'Facultades', path: '/academic/accreditation#Facultades-Programas-Acreditados' },
          { label: 'Tabla de datos', path: '/academic/accreditation#Tabla-Acreditaciones' }
        ]
      },
      {
        name: 'Programas',
        items: [
          { label: 'Información', path: '/academic/programs#info-programs' },
          { label: 'Metodología', path: '/academic/programs#Distribucion-programas-metodologia' },
          { label: 'Facultades', path: '/academic/programs#Distribucion-programas-facultad' },
          { label: 'Mapa sedes', path: '/academic/programs#mapa-programas-sede-cread' },
          { label: 'Tabla de datos', path: '/academic/programs#Tabla-programas' }
        ]
      },
      {
        name: 'Estudiantes',
        items: [
          { label: 'Intro matriculados', path: '/academic/students#estudiantes-info' },
          { label: 'Género', path: '/academic/students#estudiantes-matriculados-Genero' },
          { label: 'Facultad', path: '/academic/students#estudiantes-matriculados-facultad' },
          { label: 'Mapa dpto/pais', path: '/academic/students#estudiantes-dpto-pais-procedencia' },
          { label: 'Tabla de datos', path: '/academic/students#tabla-estudiantes' }
        ]
      },
      {
        name: 'Datos Académicos',
        items: [
          { label: 'Doble Programa', path: '/academic/data' },
          { label: 'Datos de Ingreso y Matrícula', path: '/academic/data' },
          { label: 'Promedio de Ingreso', path: '/academic/data' },
          { label: 'Transferencias Internas', path: '/academic/data' },
          { label: 'Transferencias Externas', path: '/academic/data' },
          { label: 'Promedio Acumulado', path: '/academic/data' },
          { label: 'Distribución Promedio', path: '/academic/data' },
          { label: 'Modalidad Académica', path: '/academic/data' },
          { label: 'Semestre de grado', path: '/academic/data' }
        ]
      }
    ]
  },
  {
    name: 'RSU',
    subMenus: [
      {
        name: null,
        items: [
          { label: 'Trabajo Social', path: '/rsu' },
          { label: 'Inclusión Social', path: '/rsu' }
        ]
      }
    ]
  },
  {
    name: 'TALENTO HUMANO',
    subMenus: [
      {
        name: null,
        items: [
          { label: 'Descripción', path: '/talento-humano/#descripcion-docente' },
          { label: 'Datos de Personal', path: '/talento-humano' },
          { label: 'Género', path: '/talento-humano#docentes-sexo' },
          { label: 'Escolaridad', path: '/talento-humano#docentes-escolaridad-sexo' }
        ]
      }
    ]
  },
  {
    name: 'GRADUADOS',
    subMenus: [
      {
        name: null,
        items: [
          { label: 'Informacion', path: '/graduate/#informacion-graduado' },
          { label: 'Genero', path: '/graduate#genero-graduado' },
          { label: 'Facultad', path: '/graduate' },
          { label: 'Programa', path: '/graduate' }
        ]
      }
    ]
  },
  {
    name: 'EDUCACIÓN CONTINUA',
    subMenus: [
      {
        name: null,
        items: [{ label: 'Programas Educación Continua', path: '/educacion-continua' }]
      }
    ]
  },
  {
    name: 'MOVILIDAD',
    subMenus: [
      {
        name: null,
        items: [{ label: 'Nacionales', path: '/movilidad' }]
      }
    ]
  }
];

const NavBar = () => {
  // Estado para hover (escritorio)
  const [activeMenu, setActiveMenu] = useState(null);
  const [hoveredSubMenu, setHoveredSubMenu] = useState(null);
  
  // Estados para mobile
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [openAccordion, setOpenAccordion] = useState({});

  // Función para cerrar el menú al seleccionar un link en mobile
  const handleLinkClick = () => {
    if (isMobileMenuOpen) {
      setIsMobileMenuOpen(false);
      setOpenAccordion({});
    }
  };

  // Toggle del menú principal en mobile
  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  // Función para el acordeón en mobile: abrir/cerrar la sección
  const toggleAccordion = (menuName) => {
    setOpenAccordion(prev => ({
      ...prev,
      [menuName]: !prev[menuName]
    }));
  };

  // Manejar click en el botón principal del ítem
  const handleMenuClick = (menuName) => {
    if (isMobileMenuOpen) {
      toggleAccordion(menuName);
    }
  };

  return (
    <nav className="navbar">
      {/* Botón hamburguesa: visible solo en mobile */}
      <button className="mobile-menu-button" onClick={toggleMobileMenu}>
        ☰
      </button>

      {/* Contenedor de la navegación; en mobile se alterna la clase "open" */}
      <div className={`nav-items ${isMobileMenuOpen ? 'open' : ''}`}>
        {menuItems.map(menu => (
          <div
            className="nav-item"
            key={menu.name}
            onMouseEnter={() => {
              if (!isMobileMenuOpen) {
                setActiveMenu(menu.name);
                setHoveredSubMenu(null);
              }
            }}
            onMouseLeave={() => {
              if (!isMobileMenuOpen) {
                setActiveMenu(null);
                setHoveredSubMenu(null);
              }
            }}
          >
            <button 
              className="nav-button" 
              onClick={() => handleMenuClick(menu.name)}
            >
              {menu.name}
            </button>

            { ( (!isMobileMenuOpen && activeMenu === menu.name) ||
              (isMobileMenuOpen && openAccordion[menu.name]) ) && (
              menu.name === 'ACADEMICO' ? (
                <div className="dropdown-menu two-columns">
                  <div className="submenu-titles">
                    {menu.subMenus.map((sm, idx) => (
                      sm.name && (
                        <div
                          key={idx}
                          className="submenu-title"
                          onMouseEnter={() => {
                            if (!isMobileMenuOpen) {
                              setHoveredSubMenu(sm.name);
                            }
                          }}
                        >
                          {sm.name}
                        </div>
                      )
                    ))}
                  </div>
                  <div className="submenu-items">
                    {menu.subMenus
                      // En mobile se muestran todos los submenús; en desktop solo el hovered
                      .filter(sm => isMobileMenuOpen || sm.name === hoveredSubMenu)
                      .map((sm, idx) => (
                        <ul key={idx}>
                          {sm.items.map((item, i) => (
                            <li key={i}>
                              <Link 
                                to={item.path} 
                                className="nav-link"
                                onClick={handleLinkClick}  // Cierra el menú mobile al seleccionar un link
                              >
                                {item.label}
                              </Link>
                            </li>
                          ))}
                        </ul>
                      ))}
                  </div>
                </div>
              ) : (
                <div className="dropdown-menu single-column">
                  {menu.subMenus.map((subMenu, idx) =>
                    subMenu.items && subMenu.items.map((item, i) => (
                      <Link 
                        key={i} 
                        to={item.path} 
                        className="nav-link"
                        onClick={handleLinkClick}  // Cierra el menú mobile al seleccionar un link
                      >
                        {item.label}
                      </Link>
                    ))
                  )}
                </div>
              )
            )}
          </div>
        ))}
      </div>
    </nav>
  );
};

export default NavBar;
